// package.json — NEW DEPENDENCY, not in better-auth core
//   "@better-auth/api-key": "1.7.5"

import { betterAuth } from "better-auth";
import { apiKey } from "@better-auth/api-key";   // NOT "better-auth/plugins"

export const auth = betterAuth({
  database: /* your adapter */,
  plugins: [
    apiKey({
      // SECURITY: the option is enableSessionForAPIKeys, NOT disableSessionForAPIKeys.
      // Default is already false (no mock session). Set it explicitly as a tripwire —
      // a future maintainer flipping this to true grants every API key its owner's
      // full session, admin included.
      enableSessionForAPIKeys: false,

      apiKeyHeaders: "x-api-key",          // default; string | string[]
      defaultKeyLength: 64,                // default, excludes prefix
      // enableMetadata: LEAVE FALSE — see gotchas; the key OWNER can write metadata.
      enableMetadata: false,

      keyExpiration: {
        defaultExpiresIn: null,            // null = never
        disableCustomExpiresTime: true,    // stop clients choosing their own TTL
        minExpiresIn: 1, maxExpiresIn: 365 // days
      },
      rateLimit: { enabled: false },       // default is enabled, 10 req/DAY — see gotchas
      permissions: {
        // server-side default grant; also accepts (referenceId, ctx) => Awaitable<Statements>
        defaultPermissions: { mcp: ["read"] }
      },
    }),
  ],
});

// Mint through our own POST /api/keys — server-side call, so `permissions` is allowed:
const created = await auth.api.createApiKey({
  body: {
    name: "ci-bot",
    userId: ownerId,                 // stored in the `referenceId` column, not `userId`
    prefix: "mcpr_",                 // plaintext, counts toward key length
    expiresIn: 60 * 60 * 24 * 30,    // SECONDS
    permissions: { mcp: ["all"] },   // Record<string, string[]> — server-only
  },
});
created.key;   // full plaintext, ONLY returned here
created.start; // "mcpr_x" — first 6 chars incl. prefix, safe to show in UI

// Verify on the gateway hot path — server-only, there is no HTTP route for this:
const res = await auth.api.verifyApiKey({
  body: { key: incomingHeader, permissions: { mcp: ["all"] } },
});
// res => { valid: boolean, error: {message,code} | null, key: ApiKey | null }
// It RETURNS {valid:false}, it does not throw.

